import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n == 1:
        return 'C' if opp_last == 'C' else 'D'

    opp_c = 0
    my_c = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        if m == 'C':
            my_c += 1
        if m == 'C':
            if o == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if o == 'C':
                dc += 1
            else:
                dd += 1

    opp_d = n - opp_c
    my_d = n - my_c

    # Near the end, convert cooperation into exploitation if the opponent is a strong reciprocator.
    if n >= 96:
        if opp_c >= int(n * 0.6) and opp_last == 'C':
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C'

    # If opponent almost never defects, keep cooperating but probe late occasionally.
    if opp_d <= 1:
        if n >= 88 and opp_last == 'C':
            return 'D'
        if n < 88 and n >= 40 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # Very high cooperation rate: maintain mutual cooperation.
    if opp_c * 20 >= n * 17:
        if opp_last == 'D':
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        if n >= 80 and opp_last == 'C' and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Very high defection rate: punish and stop being exploited.
    if opp_d * 20 >= n * 15:
        if opp_last == 'C' and rng.random() < 0.12:
            return 'C'
        return 'D'

    # Detect current opponent defection streak.
    opp_streak = 1
    for i in range(n - 1, 0, -1):
        if history[i][1] == history[i - 1][1]:
            opp_streak += 1
        else:
            break

    # Detect current own defection streak.
    my_streak = 1
    for i in range(n - 1, 0, -1):
        if history[i][0] == history[i - 1][0]:
            my_streak += 1
        else:
            break

    # After a long opponent defection streak, occasionally test cooperation
    # to recover mutual cooperation, but mostly keep defecting.
    if opp_last == 'D' and opp_streak >= 4:
        if my_streak >= 3 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # After a long opponent cooperation streak, cooperate, with rare late probes.
    if opp_last == 'C' and opp_streak >= 5:
        if n >= 85 and rng.random() < 0.2:
            return 'D'
        if n < 85 and rng.random() < 0.04 and dc > 0:
            return 'D'
        return 'C'

    # Forgiveness / reconciliation logic based on recent history.
    if opp_last == 'C':
        # If we defected last round and opponent still cooperated, be more likely to cooperate
        # to reward their generosity, but keep some pressure if we've been exploited a lot.
        if my_last == 'D':
            if cd > dc + 2:
                if rng.random() < 0.7:
                    return 'C'
                return 'D'
            return 'C'
        # Opponent cooperated and we did too: usually cooperate.
        if n >= 75 and rng.random() < 0.1 and dc > 0:
            return 'D'
        return 'C'
    else:
        # Opponent just defected.
        if my_last == 'D':
            # Both defected: mostly continue defecting, but occasionally try to break out.
            if opp_streak >= 3 and rng.random() < 0.2:
                return 'C'
            return 'D'
        else:
            # We cooperated, they defected: retaliate, with small forgiveness chance
            # if the opponent has generally been cooperative.
            if opp_c * 20 >= n * 13 and rng.random() < 0.25:
                return 'C'
            return 'D'
